import java.util.*; abstract class Customer08{double amount;Customer08(double a){amount=a;}abstract double bill();abstract String type();} class Student08 extends Customer08{Student08(double a){super(a);}double bill(){return amount*.9;}String type(){return "Student";}} class Staff08 extends Customer08{Staff08(double a){super(a);}double bill(){return amount*.95;}String type(){return "Staff";}} class Guest08 extends Customer08{Guest08(double a){super(a);}double bill(){return amount+10;}String type(){return "Guest";}} public class Week08Problem01{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=Integer.parseInt(s.nextLine().trim());double total=0;for(int i=0;i<n;i++){String[]p=s.nextLine().trim().split("\\s+");String t=p[0].toUpperCase();double a=Double.parseDouble(p[1]);Customer08 c=t.equals("STUDENT")?new Student08(a):t.equals("STAFF")?new Staff08(a):new Guest08(a);System.out.printf("%s: %.2f%n",c.type(),c.bill());total+=c.bill();}System.out.printf("Total: %.2f%n",total);}}